const projects = [
  {
    image: "/4635743.jpg",
    title: "CarDekho Car Price Prediction",
    text: "Machine Learning project for used-car price prediction using preprocessing, feature engineering, model training, evaluation, and hyperparameter tuning.",
    link: "https://github.com/Moses360-co/cardho",
  },
  {
    image: "/4635741.png",
    title: "Deep Learning & Neural Networks",
    text: "Current learning project covering activation functions, neural networks, image recognition, CNN, NLP, RNN, and speech recognition.",
    link: "#contact",
  },
  {
    image: "/4635743.jpg",
    title: "Python & Django E-commerce",
    text: "E-commerce website using Python and Django with product listings, shopping cart, authentication, database management, and backend functionality.",
    link: "#contact",
  },
  {
    image: "/4635741.png",
    title: "React JS & Django E-commerce",
    text: "Full-stack e-commerce application using ReactJS frontend and Django backend with products, cart, authentication, APIs, and database management.",
    link: "#contact",
  },
  {
    image: "/4635749.jpg",
    title: "JavaScript E-commerce",
    text: "Responsive perfume e-commerce project using JavaScript, HTML, and CSS with product listings, shopping cart, and interactive UI.",
    link: "#contact",
  },
];

function Projects() {
  return (
    <section className="section" id="projects">
      <h2 className="sub-title">
        Latest <span>Projects</span>
      </h2>

      <div className="portfolio-content">
        {projects.map((project) => (
          <article
            className="project-card reveal"
            key={project.title}
          >
            <img
              src={project.image}
              alt={project.title}
            />

            <div className="layer">
              <h5>{project.title}</h5>

              <p>{project.text}</p>

              <a
                href={project.link}
                target={
                  project.link.startsWith("http")
                    ? "_blank"
                    : undefined
                }
                rel="noreferrer"
              >
                <i className="bx bx-link-external"></i>
              </a>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

export default Projects;
